import { useState, type ReactNode } from "react";
import { Link, Route, Switch, useLocation } from "wouter";
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { ArrowUpRight, ChevronRight, CircleAlert, Database, Download, ExternalLink, FileText, Layers3, Share2, MapPinned, Menu, Orbit, RefreshCw, SlidersHorizontal, X } from "lucide-react";
import { calculatePasi, getMission, getSite, missions, sites, sources, type Axis, type Availability, type MissionId, type MeasurementInput, type PasiResult, type Site } from "@shared/pathfinderData";
import { copy, type Copy, type Lang } from "./lib/i18n";
import { trpc } from "./lib/trpc";
import MapView, { MarsTrekMap, WadiMap } from "./components/MapView";
import "./index.css";

const axes: Axis[] = ["surface", "topography", "thermal", "hydrology", "operations"];
const bodyColor: Record<Site["body"], string> = { Earth: "earth", Mars: "mars", Moon: "moon" };

function App() {
  const query = typeof window !== "undefined" ? new URLSearchParams(window.location.search) : null;
  const [lang, setLang] = useState<Lang>("en");
  const [earthId, setEarthId] = useState(query?.get("earth") ?? "wadi-hauran");
  const [planetId, setPlanetId] = useState(query?.get("planet") ?? "gale-crater");
  const [missionId, setMissionId] = useState<MissionId>((query?.get("mission") as MissionId) || "rover");
  const [weights, setWeights] = useState<Partial<Record<Axis, number>>>({});
  const [measurements, setMeasurements] = useState<MeasurementInput>(() => { try { return JSON.parse(query?.get("measurements") ?? "{}"); } catch { return {}; } });
  const [result, setResult] = useState<PasiResult>(() => { let initial: MeasurementInput = {}; try { initial = JSON.parse(query?.get("measurements") ?? "{}"); } catch { /* invalid shared measurements are ignored */ } return calculatePasi(query?.get("earth") ?? "wadi-hauran", query?.get("planet") ?? "gale-crater", (query?.get("mission") as MissionId) || "rover", {}, initial); });
  const [mobileOpen, setMobileOpen] = useState(false);
  const t = copy[lang];
  const rerun = (nextEarth = earthId, nextPlanet = planetId, nextMission = missionId, nextWeights = weights, nextMeasurements = measurements) => setResult(calculatePasi(nextEarth, nextPlanet, nextMission, nextWeights, nextMeasurements));
  const changeEarth = (id: string) => { setEarthId(id); rerun(id, planetId, missionId, weights); };
  const changePlanet = (id: string) => { setPlanetId(id); rerun(earthId, id, missionId, weights); };
  const changeMission = (id: MissionId) => { setMissionId(id); setWeights({}); rerun(earthId, planetId, id, {}); };
  const changeWeight = (axis: Axis, value: number) => { const next = { ...weights, [axis]: value }; setWeights(next); rerun(earthId, planetId, missionId, next); };
  const changeMeasurements = (next: MeasurementInput) => { setMeasurements(next); rerun(earthId, planetId, missionId, weights, next); };
  return (
    <div className="app" dir={lang === "ar" ? "rtl" : "ltr"}>
      <SiteShell lang={lang} setLang={setLang} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} t={t} />
      <main className="main-shell">
        <Switch>
          <Route path="/" component={() => <ShowcasePage t={t} lang={lang} />} />
          <Route path="/showcase" component={() => <ShowcasePage t={t} lang={lang} />} />
          <Route path="/workspace" component={() => <HomePage t={t} lang={lang} />} />
          <Route path="/atlas" component={() => <AtlasPage t={t} lang={lang} />} />
          <Route path="/compare" component={() => <ComparePage t={t} lang={lang} earthId={earthId} planetId={planetId} missionId={missionId} weights={weights} measurements={measurements} result={result} onEarth={changeEarth} onPlanet={changePlanet} onMission={changeMission} onWeight={changeWeight} onMeasurements={changeMeasurements} rerun={() => rerun()} />} />
          <Route path="/iraq" component={() => <IraqPage t={t} lang={lang} />} />
          <Route path="/sites/:id" component={({ params }) => <SiteProfilePage t={t} lang={lang} id={params.id} />} />
          <Route path="/methodology" component={() => <MethodologyPage t={t} lang={lang} />} />
          <Route path="/sources" component={() => <SourcesPage t={t} />} />
          <Route path="/report" component={() => <ReportPage t={t} lang={lang} earthId={earthId} planetId={planetId} missionId={missionId} measurements={measurements} result={result} />} />
          <Route path="/404" component={() => <NotFound t={t} />} />
          <Route component={() => <NotFound t={t} />} />
        </Switch>
      </main>
      <footer className="footer"><div>PATHFINDER · {t.brandKicker}</div><div>{lang === "ar" ? "روابط NASA و USGS مذكورة كمصادر بيانات؛ PATHFINDER مشروع مستقل." : "NASA / USGS links are cited as data sources; PATHFINDER is an independent project."}</div></footer>
    </div>
  );
}

function SiteShell({ lang, setLang, mobileOpen, setMobileOpen, t }: { lang: Lang; setLang: (lang: Lang) => void; mobileOpen: boolean; setMobileOpen: (open: boolean) => void; t: Copy }) {
  const [location] = useLocation();
  const links = [["/showcase", t.nav.showcase], ["/atlas", t.nav.atlas], ["/compare", t.nav.compare], ["/iraq", t.nav.iraq], ["/methodology", t.nav.method], ["/sources", t.nav.sources]];
  return <header className="topbar">
    <div className="topbar-inner">
      <Link href="/" className="brand" onClick={() => setMobileOpen(false)}><img className="team-logo" src="/pathfinder-mark.svg" alt="PATHFINDER" /><span><b>PATHFINDER</b><small>{t.brandKicker}</small></span></Link>
      <button className="mobile-menu" onClick={() => setMobileOpen(!mobileOpen)} aria-label="Toggle navigation">{mobileOpen ? <X size={20} /> : <Menu size={20} />}</button>
      <nav className={mobileOpen ? "nav mobile-visible" : "nav"}>{links.map(([href, label]) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={location === href ? "active" : ""}>{label}</Link>)}<Link href="/report" onClick={() => setMobileOpen(false)} className={location === "/report" ? "active report-link" : "report-link"}><FileText size={14} /> {t.nav.report}</Link></nav>
      <button className="language-toggle" onClick={() => setLang(lang === "en" ? "ar" : "en")}><span>{lang === "en" ? "ع" : "EN"}</span><small>{lang === "en" ? "العربية" : "English"}</small></button>
    </div>
  </header>;
}

function ShowcasePage({ t, lang }: { t: Copy; lang: Lang }) {
  const wadi = getSite("wadi-hauran")!; const gale = getSite("gale-crater")!; const result = calculatePasi("wadi-hauran", "gale-crater", "rover");
  const showcaseSources = ["jpl-mars-trek", "usgs-mars-geologic-maps", "curiosity-mount-sharp-route", "nasa-worldview", "nasa-earth-globe", "nasa-mars-globe", "perseverance-raw-images"].map(id => sources.find(source => source.id === id)!).filter(Boolean);
  const isAr = lang === "ar";
  return <div className="page showcase-page"><section className="showcase-hero"><div className="showcase-hero-copy"><span className="eyebrow"><span className="eyebrow-dot" /> {isAr ? "دليل البقاء بين الكواكب" : "INTERPLANETARY SURVIVAL GUIDE"}</span><h1>{isAr ? "خريطة المريخ التي تساعد الإنسان على الاستكشاف." : "A Martian map built for human exploration."}</h1><p>{isAr ? "نجمع طبقات التضاريس والجيولوجيا والصور وسياق المهمة في واجهة واحدة تساعد طاقم المريخ على فهم الطريق والهدف قبل الخروج." : "We combine terrain, geology, imagery, and mission context into one map that helps a Mars crew understand the route and the science target before a Marswalk."}</p><div className="hero-actions"><Link href="/compare" className="button primary">{isAr ? "شاهد المقارنة الحية" : "Watch the live comparison"} <ArrowUpRight size={16} /></Link><Link href="/atlas" className="button ghost">{isAr ? "استكشف الأطلس" : "Explore the atlas"}</Link></div></div><div className="showcase-hero-art"><div className="showcase-orbit orbit-a" /><div className="showcase-orbit orbit-b" /><div className="showcase-sun">☉</div><div className="showcase-earth"><img src="/earth-globe.jpg" alt="Earth" /></div><div className="showcase-mars"><img src="/mars-globe.jpg" alt="Mars" /></div><span className="showcase-label label-earth">WADI HAURAN</span><span className="showcase-label label-mars">GALE CRATER</span></div></section><section className="showcase-acts"><div className="showcase-act"><span>01</span><div><b>{isAr ? "نرصد" : "OBSERVE"}</b><h2>{isAr ? "بيانات حقيقية قبل أي قصة." : "Real data before a story."}</h2><p>{isAr ? "نضم البيانات البصرية والطبوغرافية والجيولوجية وسياق المهمات في طبقات يمكن للطاقم قراءتها." : "We combine optical, topographic, geological, and mission data into layers a crew can read."}</p></div></div><div className="showcase-act act-active"><span>02</span><div><b>{isAr ? "نقارن" : "COMPARE"}</b><h2>{isAr ? "وادي حوران × فوهة غيل." : "Wadi Hauran × Gale Crater."}</h2><p>{isAr ? "نقارن خصائص محددة مرتبطة بالمهمة، ونترك البيانات الناقصة ظاهرة بدلاً من إخفائها." : "We compare mission-relevant properties and keep missing evidence visible instead of hiding it."}</p></div></div><div className="showcase-act"><span>03</span><div><b>{isAr ? "نقرر" : "DECIDE"}</b><h2>{isAr ? "من التشابه إلى قرار قابل للشرح." : "From similarity to an explainable decision."}</h2><p>{isAr ? "تخرج النتيجة في خريطة وتقرير يمكن للفريق مناقشته وتطويره ميدانياً." : "The result becomes a map and report a team can discuss, test, and improve in the field."}</p></div></div></section><section className="showcase-comparison"><div className="showcase-section-head"><span className="eyebrow">{isAr ? "التجربة الأساسية" : "THE CORE EXPERIENCE"}</span><h2>{isAr ? "لا توجد علامة سحرية. توجد سلسلة أدلة." : "There is no magic pin. There is a chain of evidence."}</h2><p>{isAr ? "هذه هي لحظة المقارنة ذات الأولوية داخل PATHFINDER." : "This is the priority comparison inside PATHFINDER."}</p></div><div className="showcase-pair"><div className="showcase-site earth-card"><span className="body-tag earth">EARTH / IRAQ</span><strong>{isAr ? wadi.nameAr : wadi.name}</strong><small>{isAr ? "مرشح ميداني" : "Field candidate"}</small><div className="terrain-line"><i /><i /><i /><i /><i /></div><span className="showcase-coords">33.0333° N · 40.2500° E</span></div><div className="showcase-score"><span>{isAr ? "النتيجة من القياسات المتطابقة" : "Matched-measurement result"}</span><strong>{result.score === null ? "—" : result.score.toFixed(1)}</strong><small>{isAr ? "لا تُحسب الدرجة قبل توفر قياسات متطابقة" : "No score until paired measurements are available"}</small><span className="showcase-score-line"><i style={{ width: `${result.score ?? 0}%` }} /></span></div><div className="showcase-site mars-card"><span className="body-tag mars">MARS / REFERENCE</span><strong>{isAr ? gale.nameAr : gale.name}</strong><small>{isAr ? "مرجع مهمة" : "Mission reference"}</small><div className="terrain-line mars-lines"><i /><i /><i /><i /><i /></div><span className="showcase-coords">−4.5895° · 137.4417°</span></div></div><div className="showcase-cta-row"><p>{isAr ? "النتيجة ليست حكماً نهائياً؛ إنها نقطة بداية شفافة لسؤال أكبر." : "The score is not a final verdict; it is a transparent starting point for a bigger question."}</p><Link href="/report" className="text-link">{isAr ? "افتح التقرير العلمي" : "Open the scientific report"} <ChevronRight size={15} /></Link></div></section><section className="source-ribbon"><div><span className="eyebrow">{isAr ? "المشهد العلمي" : "THE EVIDENCE LANDSCAPE"}</span><h2>{isAr ? "مصادر صنعت التجربة" : "Sources behind the experience"}</h2></div><div className="source-ribbon-list">{showcaseSources.map(source => <a key={source.id} href={source.url} target="_blank" rel="noreferrer"><span>{source.publisher}</span><b>{source.title}</b><ArrowUpRight size={14} /></a>)}</div></section><section className="showcase-end"><span className="eyebrow">PATHFINDER</span><h2>{isAr ? "استكشف الموقع، ثم احكم على الفكرة." : "Explore the platform. Then judge the idea."}</h2><Link href="/compare" className="button primary">{isAr ? "ابدأ التجربة" : "Start the experience"} <ArrowUpRight size={16} /></Link></section></div>;
}

function HomePage({ t, lang }: { t: Copy; lang: Lang }) {
  const analyzed = sites.filter(s => s.status === "analyzed").length;
  const partial = sites.filter(s => s.status === "partial").length;
  return <div className="page home-page">
    <section className="hero grid-lines">
      <div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot" /> {t.heroEyebrow}</div><h1>{t.heroTitle}</h1><p>{t.heroText}</p><div className="hero-actions"><Link href="/atlas" className="button primary">{t.explore} <ArrowUpRight size={16} /></Link><Link href="/compare" className="button ghost">{t.compareTitle}</Link></div><div className="hero-note"><CircleAlert size={15} /><span>{t.candidate}</span><em>{t.candidateText}</em></div></div>
      <div className="hero-orbit" aria-hidden="true"><div className="orbit-ring ring-one" /><div className="orbit-ring ring-two" /><div className="orbit-core"><Orbit size={58} strokeWidth={1.2} /><span>EARTH → MARS</span></div><div className="orbit-dot dot-a" /><div className="orbit-dot dot-b" /></div>
    </section>
    <section className="metric-strip"><Metric value={String(sites.length)} label={t.analyzedSites} note="catalogued / not all analyzed" /><Metric value={String(analyzed)} label="Analyzed references" note="source-backed status" accent="teal" /><Metric value={String(partial)} label="Partial candidates" note="shown with caveats" accent="amber" /><Metric value="5" label={t.analyzedProperties} note="axes tracked per site" accent="coral" /></section>
    <section className="home-grid"><div className="panel feature-panel"><div className="panel-kicker"><MapPinned size={16} /> {t.priority}</div><h2>{t.priorityText}</h2><p>{lang === "ar" ? "ابدأ بمقارنة قابلة للتتبع، لا بدرجة مزعومة." : "Start with a traceable comparison, not a presumed score."}</p><div className="pair-preview"><SiteMini site={getSite("wadi-hauran")!} /><span className="pair-arrow">↔</span><SiteMini site={getSite("gale-crater")!} /></div><Link href="/compare" className="text-link">{t.compareNow} <ChevronRight size={15} /></Link></div><div className="panel evidence-panel"><div className="panel-kicker"><Database size={16} /> {t.transparent}</div><h2>{t.dataStatus}</h2><p>{t.transparentText}</p><div className="status-stack"><StatusRow color="green" label={t.statusLabels.analyzed} text="Source metadata and mission context loaded" /><StatusRow color="amber" label={t.statusLabels.partial} text="Qualitative or regional context only" /><StatusRow color="coral" label={t.statusLabels["field-validation"]} text="Boundary, raster or field check required" /><StatusRow color="muted" label={t.statusLabels.unavailable} text="Not inferred and not converted to zero" /></div><Link href="/methodology" className="text-link">{t.nav.method} <ChevronRight size={15} /></Link></div></section>
    <section className="callout"><div><span className="eyebrow">{t.caveat}</span><h2>{lang === "ar" ? "التشابه مرتبط بالمهمة، وليس تطابقاً كاملاً." : "Similarity is mission-specific, not complete equivalence."}</h2></div><p>{lang === "ar" ? "لا يحاكي أي موقع أرضي الجاذبية أو الضغط أو الإشعاع أو الفراغ أو الكيمياء الكاملة لبيئة المريخ أو القمر." : "No terrestrial site reproduces the gravity, pressure, radiation, vacuum, or full chemistry of Mars or the Moon."}</p></section>
  </div>;
}

function Metric({ value, label, note, accent = "amber" }: { value: string; label: string; note: string; accent?: string }) { return <div className={`metric metric-${accent}`}><strong>{value}</strong><span>{label}</span><small>{note}</small></div>; }
function SiteMini({ site }: { site: Site }) { return <div className="site-mini"><div className={`site-dot ${bodyColor[site.body]}`} /><div><b>{site.name}</b><small>{site.body}{site.country ? ` · ${site.country}` : ""}</small></div></div>; }
function StatusRow({ color, label, text }: { color: string; label: string; text: string }) { return <div className="status-row"><i className={`status-dot ${color}`} /><b>{label}</b><span>{text}</span></div>; }

function AtlasPage({ t, lang }: { t: Copy; lang: Lang }) {
  const [body, setBody] = useState<"all" | Site["body"]>("all");
  const [mission, setMission] = useState<"all" | MissionId>("all");
  const [showEarth, setShowEarth] = useState(true); const [showMars, setShowMars] = useState(true); const [showMoon, setShowMoon] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>("wadi-hauran");
  const filtered = sites.filter(site => (body === "all" || site.body === body) && (mission === "all" || site.missionTags.includes(mission)));
  const selected = selectedId ? getSite(selectedId) : undefined;
  return <div className="page"><PageHeading eyebrow="MAP / 01" title={t.atlasTitle} intro={t.atlasIntro} action={<Link href="/compare" className="button primary">{t.compareTitle} <ArrowUpRight size={16} /></Link>} />
    <div className="atlas-layout"><aside className="filter-rail panel"><div className="panel-heading"><SlidersHorizontal size={17} /><span>{lang === "ar" ? "مرشحات الأطلس" : "Atlas filters"}</span></div><label>{t.targetBody}<select value={body} onChange={e => setBody(e.target.value as typeof body)}><option value="all">{t.allBodies}</option><option value="Earth">Earth / الأرض</option><option value="Mars">Mars / المريخ</option><option value="Moon">Moon / القمر</option></select></label><label>{t.mission}<select value={mission} onChange={e => setMission(e.target.value as typeof mission)}><option value="all">{t.allMissions}</option>{missions.map(m => <option key={m.id} value={m.id}>{lang === "ar" ? m.labelAr : m.label}</option>)}</select></label><div className="filter-divider" /><div className="panel-heading"><Layers3 size={17} /><span>{t.layers}</span></div><Toggle checked={showEarth} onChange={setShowEarth} color="earth" label={t.earthLayer} /><Toggle checked={showMars} onChange={setShowMars} color="mars" label={t.marsLayer} /><Toggle checked={showMoon} onChange={setShowMoon} color="moon" label={t.moonLayer} /><div className="map-legend"><small>{t.mapLegend}</small><span><i className="legend-dot earth" /> Earth</span><span><i className="legend-dot mars" /> Mars</span><span><i className="legend-dot moon" /> Moon</span></div><div className="filter-count">{filtered.length} / {sites.length} {lang === "ar" ? "موقعاً ظاهراً" : "sites visible"}</div></aside><div className="map-panel"><MapView sites={filtered} showEarth={showEarth} showMars={showMars} showMoon={showMoon} onSelect={setSelectedId} lang={lang} /><div className="map-overlay"><span className="live-dot" /> {lang === "ar" ? "طبقة استكشاف تفاعلية" : "Interactive exploration layer"}<small>{lang === "ar" ? "إحداثيات الأجرام الأخرى ليست إسقاطاً على الأرض" : "Planetary coordinates are not Earth-projected"}</small></div></div><aside className="site-inspector panel">{selected ? <SiteInspector site={selected} t={t} lang={lang} /> : <div className="empty-state"><MapPinned size={28} /><p>{lang === "ar" ? "اختر علامة من الخريطة" : "Select a map marker"}</p></div>}</aside></div>
  </div>;
}

function Toggle({ checked, onChange, color, label }: { checked: boolean; onChange: (v: boolean) => void; color: string; label: string }) { return <label className="toggle-row"><button className={`toggle ${checked ? "on" : ""}`} onClick={() => onChange(!checked)} aria-pressed={checked}><span /></button><i className={`legend-dot ${color}`} /> <span>{label}</span></label>; }
function SiteInspector({ site, t, lang }: { site: Site; t: Copy; lang: Lang }) { return <div className="inspector-content"><div className="inspector-top"><span className={`body-tag ${bodyColor[site.body]}`}>{site.body}</span><span className={`status-chip ${site.status}`}>{t.statusLabels[site.status]}</span></div><h2>{lang === "ar" ? site.nameAr : site.name}</h2><p>{lang === "ar" ? site.environmentAr : site.environment}</p><div className="coordinates"><span>{site.lat.toFixed(4)}°</span><span>{site.lon.toFixed(4)}°</span></div><p className="small-copy">{lang === "ar" ? site.descriptionAr : site.description}</p><div className="inspector-actions"><Link href={`/sites/${site.id}`} className="button ghost full">{t.openProfile}</Link>{site.body === "Earth" && <Link href="/compare" className="button primary full">{t.compareNow}</Link>}</div><div className="mini-evidence">{site.evidence.map(e => <div key={e.axis} className="mini-evidence-row"><span>{lang === "ar" ? e.label : e.label}</span><StatusBadge status={e.status} t={t} /></div>)}</div></div>; }
function StatusBadge({ status, t }: { status: Availability; t: Copy }) { return <span className={`status-chip compact ${status}`}>{t.statusLabels[status]}</span>; }

function ComparePage({ t, lang, earthId, planetId, missionId, weights, measurements, result, onEarth, onPlanet, onMission, onWeight, onMeasurements, rerun }: { t: Copy; lang: Lang; earthId: string; planetId: string; missionId: MissionId; weights: Partial<Record<Axis, number>>; measurements: MeasurementInput; result: PasiResult; onEarth: (id: string) => void; onPlanet: (id: string) => void; onMission: (id: MissionId) => void; onWeight: (axis: Axis, value: number) => void; onMeasurements: (measurements: MeasurementInput) => void; rerun: () => void }) {
  const earthSites = sites.filter(s => s.body === "Earth"); const planetSites = sites.filter(s => s.body !== "Earth"); const earth = getSite(earthId)!; const planet = getSite(planetId)!; const mission = getMission(missionId);
  const chartData = axes.map(axis => ({ axis: lang === "ar" ? ({ surface: "السطح", topography: "التضاريس", thermal: "الحراري", hydrology: "المياه", operations: "العمليات" } as const)[axis] : axis, score: result.axisScores[axis] ?? 0, available: result.axisScores[axis] !== null }));
  return <div className="page"><PageHeading eyebrow="ANALYSIS / 02" title={t.compareTitle} intro={t.compareIntro} action={<Link href="/report" className="button ghost"><FileText size={16} /> {t.reportTitle}</Link>} />
    <section className="compare-controls panel"><div className="select-grid"><SelectField label={t.earthSite} value={earthId} onChange={onEarth} options={earthSites} lang={lang} /><SelectField label={t.planetSite} value={planetId} onChange={onPlanet} options={planetSites} lang={lang} /><label>{t.mission}<select value={missionId} onChange={e => onMission(e.target.value as MissionId)}>{missions.map(m => <option key={m.id} value={m.id}>{lang === "ar" ? m.labelAr : m.label}</option>)}</select></label></div><MeasurementUploader lang={lang} measurements={measurements} onChange={onMeasurements} /><div className="comparison-banner"><div><span className="eyebrow">{t.priority}</span><b>{earth.name} <span>↔</span> {planet.name}</b></div><button className="button small-button" onClick={rerun}><RefreshCw size={14} /> {lang === "ar" ? "احسب من البيانات" : "Calculate from data"}</button></div></section>
    <section className="score-hero panel"><div className="score-main"><span className="eyebrow">{lang === "ar" ? "نتيجة من القياسات المتطابقة" : "MATCHED-MEASUREMENT RESULT"} · {mission.label}</span><div className="score-number">{result.score === null ? "—" : result.score.toFixed(1)}<small>/100</small></div><div className="score-subline"><span className="score-bar"><i style={{ width: `${result.score ?? 0}%` }} /></span><b>{Math.round(result.completeness * 100)}%</b><span>{t.completeness}</span></div></div><div className="score-summary"><div className="pair-name"><SiteMini site={earth} /><span>↔</span><SiteMini site={planet} /></div><p>{lang === "ar" ? "النتيجة تستخدم الخصائص القابلة للمقارنة فقط؛ لا تُحوّل البيانات الناقصة إلى صفر." : "The result uses comparable properties only; missing data is never converted to zero."}</p><div className="score-flags"><span>{result.availableAxes.length} {lang === "ar" ? "محاور محسوبة" : "axes scored"}</span><span>{result.excludedAxes.length} {lang === "ar" ? "محاور مستبعدة" : "axes excluded"}</span></div></div></section>
    <div className="analysis-grid"><section className="panel chart-panel"><div className="section-heading"><div><span className="eyebrow">PASI AXES</span><h2>{t.axisScores}</h2></div><SlidersHorizontal size={18} /></div><div className="chart-wrap"><ResponsiveContainer width="100%" height={260}><BarChart data={chartData} layout="vertical" margin={{ left: 8, right: 16 }}><CartesianGrid strokeDasharray="3 3" stroke="#243142" horizontal={false} /><XAxis type="number" domain={[0, 100]} stroke="#718096" tickLine={false} axisLine={false} /><YAxis type="category" dataKey="axis" width={100} stroke="#bac4d1" tickLine={false} axisLine={false} /><Tooltip contentStyle={{ background: "#111a27", border: "1px solid #2b3a4f", borderRadius: 10 }} formatter={(value: number, _name, props) => [props.payload.available ? `${value.toFixed(1)} / 100` : t.noData, "PASI"]} /><Bar dataKey="score" fill="#d99a4e" radius={[0, 5, 5, 0]} /></BarChart></ResponsiveContainer></div></section><section className="panel weight-panel"><div className="section-heading"><div><span className="eyebrow">CONFIGURATION</span><h2>{t.missionWeights}</h2></div></div><p className="small-copy">{mission.description}</p>{axes.map(axis => <label className="weight-row" key={axis}><span>{lang === "ar" ? ({ surface: "السطح", topography: "التضاريس", thermal: "الحراري", hydrology: "المياه / الجليد", operations: "العمليات" } as const)[axis] : axis}</span><input type="range" min="0" max="1" step="0.05" value={weights[axis] ?? mission.weights[axis]} onChange={e => onWeight(axis, Number(e.target.value))} /><b>{Math.round((weights[axis] ?? mission.weights[axis]) * 100)}%</b></label>)}<button className="text-link button-reset" onClick={() => onMission(missionId)}>{t.resetWeights} <RefreshCw size={14} /></button></section></div>
    <section className="panel evidence-table-panel"><div className="section-heading"><div><span className="eyebrow">PROVENANCE</span><h2>{t.evidenceTable}</h2></div><Database size={18} /></div><div className="table-scroll"><table><thead><tr><th>{t.property}</th><th>{t.earth}</th><th>{t.planet}</th><th>{t.status}</th><th>{t.source}</th></tr></thead><tbody>{axes.map(axis => { const a = earth.evidence.find(e => e.axis === axis)!; const b = planet.evidence.find(e => e.axis === axis)!; return <tr key={axis}><td><b>{a.label}</b><small>{axis}</small></td><td><strong>{a.value ?? "—"}</strong><small>{a.note}</small></td><td><strong>{b.value ?? "—"}</strong><small>{b.note}</small></td><td><div className="stacked-status"><StatusBadge status={a.status} t={t} /><StatusBadge status={b.status} t={t} /></div></td><td><SourceLink id={a.sourceId ?? b.sourceId} t={t} /></td></tr>; })}</tbody></table></div></section>
    <section className="warning-grid"><div className="panel warning-panel"><div className="panel-heading"><CircleAlert size={17} /><span>{t.warnings}</span></div>{result.warnings.map(w => <p key={w}><span>•</span>{w}</p>)}</div><div className="panel rationale-panel"><div className="panel-heading"><Orbit size={17} /><span>{lang === "ar" ? "كيف قُرئت النتيجة" : "How the score was read"}</span></div>{result.rationale.length ? result.rationale.map(r => <p key={r}>{r}</p>) : <p>{t.noData}</p>}</div></section>
    <AndromedaAnalyst lang={lang} earthId={earthId} planetId={planetId} missionId={missionId} weights={weights} measurements={measurements} result={result} />
  </div>;
}

function AndromedaAnalyst({ lang, earthId, planetId, missionId, weights, measurements, result }: { lang: Lang; earthId: string; planetId: string; missionId: MissionId; weights: Partial<Record<Axis, number>>; measurements: MeasurementInput; result: PasiResult }) {
  const [question, setQuestion] = useState("");
  const analyst = trpc.pathfinder.analyze.useMutation();
  const ask = () => analyst.mutate({ earthId, planetId, missionId, weights, measurements, question: question.trim() || undefined, lang });
  const answer = analyst.data?.text;
  return <section className="panel andromeda-panel"><div className="andromeda-head"><div><span className="eyebrow">{lang === "ar" ? "ذكاء اندروميدا العراقي" : "ANDROMEDA IRAQI INTELLIGENCE"}</span><h2>{lang === "ar" ? "محلل المقارنة المرتبط بالمصادر" : "Source-grounded comparison analyst"}</h2><p>{lang === "ar" ? "اسأل عن التشابهات، درجات المحاور، نقص البيانات، أو الخطوة العلمية الجاية. يقرأ الاختيار الحالي ومصادر NASA والبيانات الحية قبل الجواب." : "Ask about similarities, axis scores, missing data, or the next scientific step. It reads the current selection, NASA sources, and live source fetches before answering."}</p></div><div className="andromeda-orb"><Orbit size={25} /><span>AI</span></div></div><div className="andromeda-input-row"><input value={question} onChange={e => setQuestion(e.target.value)} onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); ask(); } }} placeholder={lang === "ar" ? "مثلاً: شنو أقوى محور للمقارنة وليش؟" : "e.g. Which axis is strongest and why?"} /><button className="button primary" onClick={ask} disabled={analyst.isPending}>{analyst.isPending ? (lang === "ar" ? "يحلل المصادر..." : "Analyzing sources...") : (lang === "ar" ? "اسأل الذكاء" : "Ask Andromeda")}</button></div>{analyst.error && <div className="andromeda-error">{analyst.error.message}</div>}{answer && <article className="andromeda-answer"><div className="answer-meta"><span>{lang === "ar" ? "إجابة مرتبطة بالاختيار الحالي" : "Answer grounded in current selection"}</span><span>{analyst.data?.sourceIds.length ?? 0} {lang === "ar" ? "مصادر مقروءة" : "sources read"}</span></div><div className="answer-text">{answer}</div></article>}</section>;
}

function MeasurementUploader({ lang, measurements, onChange }: { lang: Lang; measurements: MeasurementInput; onChange: (measurements: MeasurementInput) => void }) {
  const [message, setMessage] = useState("");
  const loadFile = (file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const parsed = JSON.parse(String(reader.result)); const next = parsed.measurements ?? parsed; const valid: MeasurementInput = {}; for (const axis of axes) { const item = next?.[axis]; if (item && Number.isFinite(Number(item.earth)) && Number.isFinite(Number(item.planet)) && Number.isFinite(Number(item.rangeMin)) && Number.isFinite(Number(item.rangeMax)) && String(item.unit ?? "").trim() && String(item.sourceId ?? "").trim() && String(item.method ?? "").trim() && Number(item.rangeMax) > Number(item.rangeMin)) valid[axis] = { earth: Number(item.earth), planet: Number(item.planet), rangeMin: Number(item.rangeMin), rangeMax: Number(item.rangeMax), unit: String(item.unit), sourceId: item.sourceId ? String(item.sourceId) : undefined, method: item.method ? String(item.method) : undefined }; } onChange(valid); setMessage(lang === "ar" ? `${Object.keys(valid).length} محاور محملة` : `${Object.keys(valid).length} axes loaded`); } catch { setMessage(lang === "ar" ? "ملف JSON غير صالح" : "Invalid JSON measurement file"); } }; reader.readAsText(file); };
  const downloadTemplate = () => { const measurements = Object.fromEntries(axes.map(axis => [axis, { earth: null, planet: null, unit: "", rangeMin: null, rangeMax: null, sourceId: "", method: "" }])); const template = { project: "PATHFINDER — Wadi Hauran ↔ Gale Crater", earthSite: "wadi-hauran", planetSite: "gale-crater", mission: "rover", measurements }; const blob = new Blob([JSON.stringify(template, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "pathfinder-measurement-template.json"; anchor.click(); URL.revokeObjectURL(url); };
  return <div className="measurement-uploader"><div><span className="eyebrow">{lang === "ar" ? "مدخلات قابلة لإعادة الحساب" : "REPRODUCIBLE INPUTS"}</span><p>{lang === "ar" ? "ارفع JSON يحتوي قياساً لكل موقع، وحدة مشتركة، مدى تطبيع، ومصدر. لا تُقبل القيم الناقصة في الحساب." : "Upload JSON with a value for each site, a shared unit, normalization range, and source. Incomplete values are excluded."}</p></div><div className="measurement-actions"><label className="button ghost upload-label">{lang === "ar" ? "تحميل ملف القياسات" : "Load measurements"}<input type="file" accept="application/json,.json" onChange={e => loadFile(e.target.files?.[0])} /></label><button className="button ghost" onClick={downloadTemplate}>{lang === "ar" ? "تحميل القالب" : "Download template"}</button>{message && <span className="measurement-message">{message}</span>}</div></div>;
}

function SelectField({ label, value, onChange, options, lang }: { label: string; value: string; onChange: (id: string) => void; options: Site[]; lang: Lang }) { return <label>{label}<select value={value} onChange={e => onChange(e.target.value)}>{options.map(s => <option key={s.id} value={s.id}>{lang === "ar" ? s.nameAr : s.name}</option>)}</select></label>; }

function SiteProfilePage({ t, lang, id }: { t: Copy; lang: Lang; id: string }) { const site = getSite(id); if (!site) return <NotFound t={t} />; return <div className="page"><PageHeading eyebrow={`SITE PROFILE / ${site.body.toUpperCase()}`} title={lang === "ar" ? site.nameAr : site.name} intro={lang === "ar" ? site.descriptionAr : site.description} action={<Link href="/atlas" className="button ghost"><MapPinned size={16} /> {t.nav.atlas}</Link>} /><div className="profile-grid"><section className="panel profile-main"><div className="site-hero-row"><div className={`big-site-icon ${bodyColor[site.body]}`}>{site.body === "Earth" ? "E" : site.body === "Mars" ? "M" : "L"}</div><div><span className={`body-tag ${bodyColor[site.body]}`}>{site.body}{site.country ? ` · ${site.country}` : ""}</span><h2>{lang === "ar" ? site.environmentAr : site.environment}</h2><span className={`status-chip ${site.status}`}>{lang === "ar" ? site.statusLabelAr : site.statusLabel}</span></div></div><div className="profile-facts"><Fact label={t.coordinates} value={`${site.lat.toFixed(4)}°, ${site.lon.toFixed(4)}°`} /><Fact label={lang === "ar" ? "النطاق" : "Scope"} value={lang === "ar" ? site.extentAr ?? "—" : site.extent ?? "—"} /><Fact label={lang === "ar" ? "المصادر" : "Sources"} value={`${site.sourceIds.length} linked records`} /></div><h3>{t.useCases}</h3><ul className="clean-list">{(lang === "ar" ? site.useCasesAr : site.useCases).map(x => <li key={x}>{x}</li>)}</ul><h3>{t.limitations}</h3><ul className="clean-list caution-list">{(lang === "ar" ? site.limitationsAr : site.limitations).map(x => <li key={x}>{x}</li>)}</ul></section><section className="panel profile-evidence"><div className="panel-heading"><Database size={17} /><span>{t.evidenceTable}</span></div>{site.evidence.map(e => <div className="evidence-card" key={e.axis}><div className="evidence-title"><b>{e.label}</b><StatusBadge status={e.status} t={t} /></div><p>{e.note}</p>{e.sourceId && <SourceLink id={e.sourceId} t={t} />}{e.resolution && <small>{t.resolution}: {e.resolution}</small>}</div>)}</section></div><div className="panel profile-sources"><div className="panel-heading"><ExternalLink size={17} /><span>{t.source}</span></div><div className="source-grid">{site.sourceIds.map(id => <SourceCard key={id} source={sources.find(s => s.id === id)!} t={t} />)}</div></div>{site.id === "wadi-hauran" && <div className="callout safety"><div><span className="eyebrow">SAFETY / ACCESS</span><h2>{lang === "ar" ? "هذه المنصة لا تمنح تصريحاً ميدانياً." : "This platform does not authorize field access."}</h2></div><p>{lang === "ar" ? "الموقع مرشح بحثي في منطقة تتطلب تحققاً محلياً مستقلاً من السلامة والوصول والتصاريح." : "The site is a research candidate in an area requiring independent local assessment of safety, access, and permissions."}</p></div>}</div>; }
function Fact({ label, value }: { label: string; value: string }) { return <div><small>{label}</small><b>{value}</b></div>; }

function IraqPage({ t, lang }: { t: Copy; lang: Lang }) {
  const site = getSite("wadi-hauran")!;
  const checklist = lang === "ar" ? ["حدود دراسة موثقة", "نموذج DEM أرضي مقصوص ومقاييس الانحدار", "تقييم الوصول والسلامة الميدانية", "نافذة تضاريس مريخية متناظرة"] : ["Documented study boundary", "Clipped Earth DEM and slope metrics", "Field access and safety assessment", "Matched Mars terrain window"];
  return <div className="page"><PageHeading eyebrow="IRAQ / 03" title={t.iraqTitle} intro={t.iraqIntro} action={<Link href="/sites/wadi-hauran" className="button primary">{t.openProfile} <ArrowUpRight size={16} /></Link>} /><div className="iraq-grid"><section className="panel iraq-hero"><span className="eyebrow">{lang === "ar" ? "موقع مرشح / وادي حوران" : "CANDIDATE SITE / WADI HAURAN"}</span><h2>{lang === "ar" ? site.nameAr : site.name}</h2><p>{lang === "ar" ? site.descriptionAr : site.description}</p><WadiMap lang={lang} /><div className="wadi-map-links"><a href="https://worldview.earthdata.nasa.gov/" target="_blank" rel="noreferrer"><b>{lang === "ar" ? "استكشف طبقات NASA للأرض" : "Explore NASA Earth layers"}</b><span>NASA Worldview / GIBS <ArrowUpRight size={13} /></span></a><a href="https://trek.nasa.gov/mars/" target="_blank" rel="noreferrer"><b>{lang === "ar" ? "افتح مرجع المريخ" : "Open the Mars reference"}</b><span>NASA Mars Trek <ArrowUpRight size={13} /></span></a></div><Link href="/compare" className="text-link">{t.compareNow} ↔ {getSite("gale-crater")!.name} <ChevronRight size={15} /></Link></section><section className="panel iraq-checklist"><div className="panel-heading"><CircleAlert size={17} /><span>{lang === "ar" ? "ما يحتاج إلى بيانات" : "What still needs data"}</span></div>{checklist.map((x, i) => <div className="check-row" key={x}><span>0{i + 1}</span><b>{x}</b><StatusBadge status={i === 2 ? "field-validation" : "partial"} t={t} /></div>)}<div className="divider-note">{lang === "ar" ? "لا نعرض غياب البيانات كدرجة صفر." : "Missing data is not rendered as a score of zero."}</div></section></div><section className="panel mars-bridge-panel"><div className="section-heading"><div><span className="eyebrow">{lang === "ar" ? "جسر الأرض ↔ المريخ" : "EARTH ↔ MARS BRIDGE"}</span><h2>{lang === "ar" ? "الخريطتان الحقيقيتان، كل واحدة بإسقاطها" : "Two real maps, each in its native reference"}</h2><p>{lang === "ar" ? "خريطة وادي حوران تستخدم NASA GIBS للأرض، وخريطة غيل تستخدم NASA Mars Trek مع MOLA وTHEMIS وHiRISE." : "Wadi Hauran uses NASA GIBS for Earth; Gale uses NASA Mars Trek with MOLA, THEMIS, and HiRISE."}</p></div><a className="button ghost" href="https://trek.nasa.gov/mars/" target="_blank" rel="noreferrer">{lang === "ar" ? "فتح Mars Trek" : "Open Mars Trek"} <ArrowUpRight size={15} /></a></div><MarsTrekMap lang={lang} /></section><section className="panel"><div className="section-heading"><div><span className="eyebrow">{lang === "ar" ? "مسار الأدلة" : "EVIDENCE THREAD"}</span><h2>{lang === "ar" ? "لماذا هذا الموقع؟" : "Why this site?"}</h2></div></div><div className="timeline"><div><span>01</span><p><b>{lang === "ar" ? "جيومورفولوجيا الوادي" : "Wadi geomorphology"}</b><br />{lang === "ar" ? "شبكات تصريف وأشكال تعرية موثقة في الدراسة الجيولوجية." : "Drainage networks and erosional forms are documented in the geology study."}</p></div><div><span>02</span><p><b>{lang === "ar" ? "سياق المريخ" : "Mars context"}</b><br />{lang === "ar" ? "تُستخدم غيل كمرجع لتحديد ما يمكن مقارنته وما لا يمكن." : "Gale is used as a reference to make comparable and non-comparable properties explicit."}</p></div><div><span>03</span><p><b>{lang === "ar" ? "الخطوة التالية" : "Next evidence step"}</b><br />{lang === "ar" ? "إدخال DEM مقصوص وحدود دراسة موثقة قبل أي ادعاء رقمي للتضاريس." : "Ingest a clipped DEM and documented study boundary before a numerical terrain claim."}</p></div></div></section><section className="panel iraq-data-stack"><div className="section-heading"><div><span className="eyebrow">{lang === "ar" ? "حزمة البيانات" : "DATA STACK"}</span><h2>{lang === "ar" ? "ما الذي يدخل فعلاً في دراسة العراق؟" : "What actually enters the Iraq study?"}</h2></div></div><div className="iraq-data-grid">{["wadi-geology", "srtm", "nasa-worldview", "ecostress"].map(id => { const source = sources.find(x => x.id === id)!; return <a key={id} href={source.url} target="_blank" rel="noreferrer"><b>{source.title}</b><span>{source.publisher}</span><small>{id === "wadi-geology" ? (lang === "ar" ? "سياق جيولوجي وجيومورفولوجي للوادي" : "Geologic and geomorphic context for the wadi") : id === "srtm" ? (lang === "ar" ? "مرجع نموذج الارتفاع الأرضي" : "Earth DEM provenance for a future clipped window") : id === "nasa-worldview" ? (lang === "ar" ? "صور ومشاهدة سطح الأرض" : "Earth observation imagery context") : (lang === "ar" ? "حرارة سطح الأرض من ECOSTRESS" : "Earth surface temperature context from ECOSTRESS")}</small><ArrowUpRight size={14} /></a>; })}</div></section></div>;
}

function MethodologyPage({ t, lang }: { t: Copy; lang: Lang }) {
  const rules = lang === "ar" ? ["تدخل الخصائص المقاسة والمتوافقة فقط في الحساب.", "كل محور يحتاج قيمة Earth وقيمة Mars أو Moon بنفس الوحدة والطريقة.", "عند غياب زوج قياسات، يبقى المحور بدون نتيجة ولا يتحول إلى رقم افتراضي."] : ["Only measured, compatible properties enter the calculation.", "Every axis needs an Earth value and a Mars or Moon value in the same unit and method.", "When a paired measurement is missing, the axis stays unscored instead of becoming an invented number."];
  return <div className="page"><PageHeading eyebrow="METHOD / 04" title={t.methodologyTitle} intro={t.methodologyIntro} /><div className="method-grid"><section className="panel formula-panel"><span className="eyebrow">{lang === "ar" ? "حساب قابل للتدقيق" : "AUDITABLE CALCULATION"}</span><div className="formula">PASI = 100 × <span>Σ(wᵢ × sᵢ)</span> / <span>Σ(wᵢ)</span></div><p>{t.formula}</p>{rules.map((rule, i) => <div className="method-rule" key={rule}><b>0{i + 1}</b><span>{rule}</span></div>)}</section><section className="panel"><div className="panel-heading"><SlidersHorizontal size={17} /><span>{lang === "ar" ? "جاهزية القياس" : "Measurement readiness"}</span></div><p className="body-copy">{lang === "ar" ? "المقارنة الحالية تعرض مصدر كل مدخل وإطاره ودقته. لن تظهر درجة للموقعين حتى تُحمّل قياسات متطابقة قابلة لإعادة الحساب." : "The comparison exposes the source, coordinate frame, and resolution of every input. A site pair does not receive a score until matched measurements are loaded and reproducible."}</p><div className="mission-list">{missions.map(m => <div className="mission-row" key={m.id}><b>{lang === "ar" ? m.labelAr : m.label}</b><span>{Object.entries(m.weights).map(([k, v]) => `${k}: ${Math.round(v * 100)}%`).join(" · ")}</span></div>)}</div></section></div></div>;
}

function SourcesPage({ t }: { t: Copy }) { return <div className="page"><PageHeading eyebrow="PROVENANCE / 05" title={t.sourcesTitle} intro={t.sourcesIntro} /><div className="source-grid full-source-grid">{sources.map(source => <SourceCard key={source.id} source={source} t={t} large />)}</div></div>; }
function SourceCard({ source, t, large = false }: { source: typeof sources[number]; t: Copy; large?: boolean }) { return <article className={`source-card ${large ? "large" : ""}`}><div className="source-card-top"><span className="source-id">{source.id}</span><ExternalLink size={15} /></div><h3>{source.title}</h3><p>{source.description}</p><div className="source-meta"><span>{source.publisher}</span>{source.date && <span>{t.date}: {source.date}</span>}{source.resolution && <span>{t.resolution}: {source.resolution}</span>}</div><a href={source.url} target="_blank" rel="noreferrer">{t.sourceLink} <ArrowUpRight size={14} /></a></article>; }
function SourceLink({ id, t }: { id?: string; t: Copy }) { const source = sources.find(s => s.id === id); return source ? <a className="source-link" href={source.url} target="_blank" rel="noreferrer">{source.publisher} <ExternalLink size={12} /></a> : <span className="muted">{t.noData}</span>; }

function ReportPage({ t, lang, earthId, planetId, missionId, measurements, result }: { t: Copy; lang: Lang; earthId: string; planetId: string; missionId: MissionId; measurements: MeasurementInput; result: PasiResult }) {
  const earth = getSite(earthId)!; const planet = getSite(planetId)!; const mission = getMission(missionId);
  const sourceIds = Array.from(new Set([...(earth.sourceIds ?? []), ...(planet.sourceIds ?? []), "nasa-gibs", "mars-trek-wmts", "challenge-martian-map", "judging-guide"]));
  const [shareState, setShareState] = useState("");
  const measurementQuery = Object.keys(measurements).length ? `&measurements=${encodeURIComponent(JSON.stringify(measurements))}` : "";
  const shareUrl = typeof window !== "undefined" ? `${window.location.origin}/report?earth=${encodeURIComponent(earthId)}&planet=${encodeURIComponent(planetId)}&mission=${encodeURIComponent(missionId)}${measurementQuery}` : "/report";
  const shareReport = async () => { try { if (navigator.share) await navigator.share({ title: `PATHFINDER · ${earth.name} ↔ ${planet.name}`, text: t.reportTitle, url: shareUrl }); else { await navigator.clipboard.writeText(shareUrl); setShareState(t.shareCopied); window.setTimeout(() => setShareState(""), 2600); } } catch (error) { if (!(error instanceof DOMException && error.name === "AbortError")) { try { await navigator.clipboard.writeText(shareUrl); setShareState(t.shareCopied); window.setTimeout(() => setShareState(""), 2600); } catch { setShareState(shareUrl); } } } };
  return <div className="page report-page"><div className="report-toolbar"><div><span className="eyebrow">{lang === "ar" ? "تقرير / مولد من التحليل الحالي" : "REPORT / GENERATED FROM CURRENT ANALYSIS"}</span><h1>{t.reportTitle}</h1></div><div className="report-actions no-print"><button className="button ghost" onClick={shareReport}><Share2 size={16} /> {t.shareReport}</button><button className="button primary" onClick={() => window.print()}><Download size={16} /> {t.print}</button>{shareState && <span className="share-status">{shareState}</span>}</div></div><article className="report-paper"><div className="report-cover"><img className="report-team-logo" src="/pathfinder-mark.svg" alt="PATHFINDER" /><span className="eyebrow">PATHFINDER · {lang === "ar" ? "تقرير موقع علمي" : "SCIENTIFIC SITE REPORT"}</span><h2>{lang === "ar" ? earth.nameAr : earth.name} <span>↔</span> {lang === "ar" ? planet.nameAr : planet.name}</h2><p>{t.reportIntro}</p><div className="report-stamp">{lang === "ar" ? mission.labelAr : mission.label} · {new Date().toISOString().slice(0, 10)}</div></div><section><h3>{lang === "ar" ? "1. الملخص التنفيذي" : "1. Executive summary"}</h3><p>{lang === "ar" ? `تنتج المقارنة الحالية درجة PASI مقدارها ${result.score === null ? "غير محسوبة" : result.score} مع اكتمال بيانات قدره ${Math.round(result.completeness * 100)}٪. هذه نتيجة داخلية مرتبطة بالمهمة ولا تثبت أن الموقعين متكافئان كوكبياً.` : `The current comparison produces a PASI score of ${result.score === null ? "not computed" : result.score} with ${Math.round(result.completeness * 100)}% weighted data completeness. This is a mission-specific internal result, not proof that the sites are planetary equivalents.`}</p></section><section><h3>{lang === "ar" ? "2. المواقع والمدخلات" : "2. Sites and inputs"}</h3><div className="report-site-grid"><ReportSite site={earth} lang={lang} /><ReportSite site={planet} lang={lang} /></div><div className="report-inputs">{[earth, planet].map(site => <div key={site.id}><b>{lang === "ar" ? site.nameAr : site.name}</b><small>{lang === "ar" ? "الإطار المرجعي" : "Coordinate frame"}: {site.coordinateFrame}</small>{site.evidence.map(e => <span key={e.axis}>{e.label}: {e.status}{e.sourceId ? ` · ${e.sourceId}` : ""}</span>)}</div>)}</div></section><section><h3>{lang === "ar" ? "3. النتائج" : "3. Results"}</h3><div className="report-score-row"><div><small>{t.score}</small><strong>{result.score ?? "—"}<em>/100</em></strong></div><div><small>{t.completeness}</small><strong>{Math.round(result.completeness * 100)}<em>%</em></strong></div><div><small>{lang === "ar" ? "المهمة" : "Mission"}</small><strong className="mission-result">{lang === "ar" ? mission.labelAr : mission.label}</strong></div></div><p className="report-weight-note"><b>{lang === "ar" ? "الأوزان المستخدمة" : "Weights used"}:</b> {Object.entries(result.weights).map(([key, value]) => `${key} ${Math.round(value * 100)}%`).join(" · ")}</p><div className="report-bars">{axes.map(axis => <div className="report-bar-row" key={axis}><span>{axis}</span><i><b style={{ width: `${result.axisScores[axis] ?? 0}%` }} /></i><strong>{result.axisScores[axis] === null ? "—" : result.axisScores[axis]!.toFixed(1)}</strong></div>)}</div><table className="report-table"><thead><tr><th>{t.property}</th><th>{lang === "ar" ? "النتيجة" : "Score"}</th><th>{t.status}</th></tr></thead><tbody>{axes.map(axis => <tr key={axis}><td>{axis}</td><td>{result.axisScores[axis] === null ? "—" : result.axisScores[axis]!.toFixed(1)}</td><td>{result.axisScores[axis] === null ? t.noData : t.statusLabels.analyzed}</td></tr>)}</tbody></table></section><section><h3>{lang === "ar" ? "4. المنهجية والقيود" : "4. Method and limitations"}</h3><p>{t.formula}. {t.methodologyIntro}</p><ul>{result.warnings.map(w => <li key={w}>{w}</li>)}</ul></section><JudgingRecommendations lang={lang} result={result} /><section><h3>{lang === "ar" ? "6. المراجع" : "6. References"}</h3><ol>{sourceIds.map(id => { const s = sources.find(x => x.id === id)!; return <li key={id}><a href={s.url} target="_blank" rel="noreferrer">{s.title}</a> — {s.publisher}</li>; })}</ol></section></article></div>;
}

function JudgingRecommendations({ lang, result }: { lang: Lang; result: PasiResult }) {
  const recommendations = lang === "ar" ? [
    ["الأثر", "أبرزوا أن PATHFINDER يحول بيانات كوكبية معقدة إلى قرار مفهوم لطاقم المريخ، مع إبقاء السلامة والبيانات الناقصة ضمن القرار."],
    ["الإبداع", "بيّنوا دمج خريطة Earth/Mars، وذكاء اندروميدا العراقي، وحساب PASI القابل لإعادة التجربة في تجربة واحدة ثنائية اللغة."],
    ["الصلاحية", `اعرضوا القياسات المرفوعة ومصادر NASA وUSGS أمام اللجنة. الدرجة الحالية ${result.score === null ? "غير محسوبة حتى تتوفر قياسات مزدوجة" : "ناتجة من القياسات المرفوعة"}، وهذا يقوي قابلية التدقيق.`],
    ["الارتباط بالتحدي", "اربطوا العرض مباشرة بخريطة مهمة Marswalk: طبقات تضاريس، سياق جيولوجي، طريق استكشاف، ومراجع Mars Trek بدلاً من الاكتفاء بعرض موقعين."],
    ["العرض", "ابدأوا بدقيقة واحدة: اختاروا Wadi Hauran وGale، حمّلوا القياسات، اسألوا ذكاء اندروميدا، ثم افتحوا التقرير وشاركوا الرابط مع اللجنة."],
  ] : [
    ["Impact", "Show how PATHFINDER turns complex planetary data into an understandable decision for a Mars crew, while keeping safety and missing evidence visible."],
    ["Creativity", "Demonstrate the combined Earth/Mars map, Andromeda Iraqi Intelligence, and reproducible PASI workflow as one bilingual experience."],
    ["Validity", `Show the uploaded measurements and NASA/USGS provenance. The current score is ${result.score === null ? "not computed until paired measurements exist" : "computed from the uploaded measurements"}, which strengthens auditability.`],
    ["Relevance", "Connect the demo directly to a Marswalk map: terrain layers, geology context, an exploration route, and Mars Trek references rather than only showing two sites."],
    ["Presentation", "Use a one-minute flow: select Wadi Hauran and Gale, load measurements, ask Andromeda Intelligence, then open and share the report."],
  ];
  return <section className="report-recommendations"><h3>{lang === "ar" ? "5. توصيات نهائية للتحكيم" : "5. Final recommendations for judging"}</h3><p>{lang === "ar" ? "هذه النقاط تساعد الفريق على عرض الفكرة وفق محاور NASA Space Apps الخمسة." : "Use these points to frame the demo against the five NASA Space Apps judging criteria."}</p><div className="recommendation-grid">{recommendations.map(([title, text]) => <div key={title}><b>{title}</b><p>{text}</p></div>)}</div></section>;
}

function ReportSite({ site, lang }: { site: Site; lang: Lang }) { return <div className="report-site"><span className={`body-tag ${bodyColor[site.body]}`}>{site.body}</span><h4>{lang === "ar" ? site.nameAr : site.name}</h4><p>{lang === "ar" ? site.descriptionAr : site.description}</p><small>{site.lat.toFixed(4)}°, {site.lon.toFixed(4)}°</small></div>; }

function PageHeading({ eyebrow, title, intro, action }: { eyebrow: string; title: string; intro: string; action?: ReactNode }) { return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{intro}</p></div>{action}</div>; }
function NotFound({ t }: { t: Copy }) { return <div className="page not-found"><Orbit size={42} /><h1>{t.notFound}</h1><p>{t.backHome}</p><Link href="/" className="button primary">{t.backHome}</Link></div>; }

export default App;
